var LF = Rune('\n')

// CRLF parses a carriage returned, followed by a line feed, used by Windows systems as the newline.
var CRLF = String("\r\n")

// NewLine matches either a Windows or Unix line break character.
var NewLine = Any(CRLF, LF)
